//! One decode of control JSON; terminal-validated metadata only, no installs.
use super::*;
use serde::Deserialize;
use std::{fs::File,path::{Path,PathBuf}};
#[derive(Deserialize)]#[serde(deny_unknown_fields)]struct Row{generator:crate::GeneratorName,path:PathBuf,state:String}
#[derive(Deserialize)]#[serde(deny_unknown_fields)]struct Diagnostic{generator:crate::GeneratorName,relative:String,line:u32,message:String}
#[derive(Deserialize)]#[serde(deny_unknown_fields)]struct FailureData{kind:crate::request_failure::FailureKind,message:String,os_code:Option<i32>,io_kind:Option<String>}
#[derive(Deserialize)]#[serde(deny_unknown_fields)]struct Warning{path:PathBuf,failure:FailureData}
#[derive(Deserialize)]#[serde(deny_unknown_fields)]struct ReportData{schema:String,clean:bool,rows:Vec<Row>,diagnostics:Vec<Diagnostic>,changed:Vec<PathBuf>,cleanup:Vec<Warning>,committed:bool}
#[derive(Deserialize)]#[serde(deny_unknown_fields)]struct FailedData{schema:String,primary:FailureData,rollback:Vec<Warning>,cleanup:Vec<Warning>,committed:bool}
#[derive(Debug)]struct Incomplete(io::Error);impl fmt::Display for Incomplete{fn fmt(&self,f:&mut fmt::Formatter<'_>)->fmt::Result{write!(f,"generation reply incomplete; output commit status is unknown: {}",self.0)}}impl Error for Incomplete{fn source(&self)->Option<&(dyn Error+'static)>{Some(&self.0)}}
struct Collector{file:File,total:u64,fragments:u32,hash:xxhash_rust::xxh3::Xxh3}
impl Collector{fn new(file:File)->Self{Self{file,total:0,fragments:0,hash:xxhash_rust::xxh3::Xxh3::new()}}fn push(&mut self,sequence:u32,offset:u64,bytes:&[u8])->io::Result<()>{if sequence!=self.fragments||offset!=self.total||bytes.is_empty()||bytes.len()>FRAGMENT{return Err(io::Error::new(io::ErrorKind::InvalidData,"generation fragment sequence/offset/size mismatch"))}let total=self.total.checked_add(bytes.len()as u64).filter(|n|*n<=OUTPUT).ok_or(io::ErrorKind::OutOfMemory)?;self.file.write_all(bytes)?;self.hash.update(bytes);self.total=total;self.fragments+=1;Ok(())}fn finish(&mut self,terminal:&GenerationTerminal)->io::Result<()>{if terminal.total!=self.total||terminal.fragments!=self.fragments||terminal.hash!=self.hash.digest128()||terminal.total==0||terminal.total>OUTPUT||terminal.status==Status::Failed&&terminal.clean{return Err(io::Error::new(io::ErrorKind::InvalidData,"generation terminal does not seal all staged fragments"))}self.file.flush()?;self.file.seek(SeekFrom::Start(0))?;Ok(())}}
#[derive(Debug)]struct RemoteFailure{message:String,cause:Box<dyn Error>,committed:bool,may_have_changed:bool}
impl fmt::Display for RemoteFailure{fn fmt(&self,f:&mut fmt::Formatter<'_>)->fmt::Result{write!(f,"{}",self.message)?;if self.committed{write!(f,"; earlier generation phases committed outputs")?}else if self.may_have_changed{write!(f,"; generation rollback incomplete; outputs may have changed")?}Ok(())}}
impl Error for RemoteFailure{fn source(&self)->Option<&(dyn Error+'static)>{Some(self.cause.as_ref())}}
fn print_failure(failure:FailureData,committed:bool,may_have_changed:bool)->RemoteFailure{let cause:Box<dyn Error>=if failure.kind==crate::request_failure::FailureKind::Source{Box::new(crate::request_failure::RequestFailure{kind:failure.kind,message:String::new()})}else if let Some(code)=failure.os_code{Box::new(io::Error::from_raw_os_error(code))}else{let kind=match failure.io_kind.as_deref(){Some("Interrupted")=>io::ErrorKind::Interrupted,Some("OutOfMemory")=>io::ErrorKind::OutOfMemory,Some("NotFound")=>io::ErrorKind::NotFound,Some("PermissionDenied")=>io::ErrorKind::PermissionDenied,Some("TimedOut")=>io::ErrorKind::TimedOut,_=>if failure.kind==crate::request_failure::FailureKind::Cancelled{io::ErrorKind::Interrupted}else{io::ErrorKind::Other}};Box::new(io::Error::new(kind,"remote native generation failed"))};RemoteFailure{message:failure.message,cause,committed,may_have_changed}}
fn selected(request:&GenerationRequest,name:crate::GeneratorName)->bool{request.build.policy_inputs.as_ref().is_some_and(|policy|policy.workspace_generators.contains(&name))}
fn completed(collector:&mut Collector,terminal:&GenerationTerminal,request:&GenerationRequest,output:&mut impl Write)->Result<bool,Box<dyn Error>>{collector.finish(terminal)?;if terminal.status==Status::Failed{let failure:FailedData=serde_json::from_reader(&mut collector.file)?;if failure.schema!="native-generation-failure-v1"||failure.committed!=terminal.committed||failure.cleanup.len()!=terminal.cleanup_warnings as usize{return Err(io::Error::new(io::ErrorKind::InvalidData,"invalid generation failure metadata").into())}for warning in &failure.rollback{eprintln!("rollback failed for {}: {}",warning.path.display(),warning.failure.message);}for warning in &failure.cleanup{eprintln!("committed cleanup warning for {}: {}",warning.path.display(),warning.failure.message);}return Err(print_failure(failure.primary,failure.committed,terminal.may_have_changed).into())}
 let report:ReportData=serde_json::from_reader(&mut collector.file)?;if report.schema!="native-generation-v1"||report.committed!=terminal.committed||terminal.may_have_changed!=terminal.committed||report.cleanup.len()!=terminal.cleanup_warnings as usize{return Err(io::Error::new(io::ErrorKind::InvalidData,"invalid generation report metadata").into())}let root=std::fs::canonicalize(&request.build.policy_inputs.as_ref().unwrap().workspace.as_ref().unwrap().root)?;for row in &report.rows{if !selected(request,row.generator)||!matches!(row.state.as_str(),"fresh"|"written"|"stale"|"not_included")||!row.path.is_absolute()||!row.path.starts_with(&root){return Err(io::Error::new(io::ErrorKind::InvalidData,"generation row differs from request scope").into())}}if report.diagnostics.iter().any(|row|!selected(request,row.generator))||report.changed.iter().any(|path|!path.is_absolute()||!path.starts_with(&root)){return Err(io::Error::new(io::ErrorKind::InvalidData,"generation metadata differs from selected scope").into())}if request.check&&(terminal.committed||terminal.may_have_changed||report.committed||!report.changed.is_empty()||report.rows.iter().any(|row|row.state=="written")){return Err(io::Error::new(io::ErrorKind::InvalidData,"completed check-only generation reply contradicts its no-write request").into())}let clean=!report.rows.is_empty()&&report.diagnostics.is_empty()&&report.cleanup.is_empty()&&report.rows.iter().all(|row|matches!(row.state.as_str(),"fresh"|"written"));if clean!=terminal.clean||report.clean!=terminal.clean{return Err(io::Error::new(io::ErrorKind::InvalidData,"generation clean flag contradicts completed rows").into())}let _=report.diagnostics.iter().fold(0usize,|n,row|n.saturating_add(row.relative.len()).saturating_add(row.message.len()).saturating_add(row.line as usize));drop(report);collector.file.seek(SeekFrom::Start(0))?;serde_json::to_writer(&mut *output,&serde_json::json!({"schema":"native-generation-batch-v1","row":"generation_batch","status":"completed","clean":terminal.clean,"committed":terminal.committed,"cleanup_warnings":terminal.cleanup_warnings}))?;output.write_all(b"\n")?;io::copy(&mut collector.file,output)?;output.write_all(b"\n")?;output.flush()?;Ok(clean)}
/// Exact explicit CLI: dmbc generate REQUEST.json --jsonl.
/// The child owns the sole control-file decode and daemon request deadline.
pub fn run_file(path:&Path)->Result<bool,Box<dyn Error>>{let mut bytes=Vec::new();File::open(path)?.take((super::super::protocol::MAX_FRAME+1)as u64).read_to_end(&mut bytes)?;if bytes.len()>super::super::protocol::MAX_FRAME{return Err(io::Error::new(io::ErrorKind::InvalidInput,"generation control request exceeds daemon frame bound").into())}let request:GenerationRequest=serde_json::from_slice(&bytes)?;request.validate()?;super::super::build_admission::validate(&request.build)?;validate_cache(&request.build)?;let cache=request.build.cache_root.as_ref().unwrap();let file=crate::generation_staging::temporary_output(cache)?;let mut collector=Collector::new(file);let mut stream=super::super::connect_generation()?;super::super::transport::set_timeout(&mut stream,super::super::transport::BUILD_DEADLINE)?;super::super::protocol::send(&mut stream,&super::super::protocol::Request::Generate(request.clone()))?;receive(&mut stream,&mut collector,&request,&mut io::stdout().lock())}
fn receive(stream:&mut super::super::transport::Stream,collector:&mut Collector,request:&GenerationRequest,output:&mut impl Write)->Result<bool,Box<dyn Error>>{let mut accepted=false;let mut diagnostics=0usize;loop{match super::super::protocol::receive_bounded::<super::super::protocol::Reply>(stream,super::super::protocol::MAX_FRAME).map_err(Incomplete)?{super::super::protocol::Reply::Accepted if !accepted=>accepted=true,super::super::protocol::Reply::Diagnostic{stdout:_,bytes}if accepted=>{diagnostics=diagnostics.checked_add(bytes.len()).filter(|n|*n<=OUTPUT as usize).ok_or_else(||io::Error::new(io::ErrorKind::OutOfMemory,"generation diagnostic bytes exceed existing output bound"))?;io::stderr().lock().write_all(&bytes)?;},super::super::protocol::Reply::GenerationFragment{sequence,offset,bytes}if accepted=>collector.push(sequence,offset,&bytes)?,super::super::protocol::Reply::GenerationFinished(terminal)if accepted=>return completed(collector,&terminal,request,output),super::super::protocol::Reply::GenerationAborted(abort)=>{let failure=FailureData{kind:abort.failure.kind,message:abort.failure.message,os_code:abort.os_code,io_kind:None};return Err(print_failure(failure,abort.committed,abort.may_have_changed).into())},super::super::protocol::Reply::Rejected(error)=>return Err(error.into()),_=>return Err(io::Error::new(io::ErrorKind::InvalidData,"unexpected generation reply; no complete report is available").into())}}}
#[cfg(test)]pub(super) fn receive_test(stream:&mut super::super::transport::Stream,request:&GenerationRequest,output:&mut impl Write)->Result<bool,Box<dyn Error>>{let file=crate::generation_staging::temporary_output(request.build.cache_root.as_ref().unwrap())?;receive(stream,&mut Collector::new(file),request,output)}

#[cfg(test)]mod tests{use super::*;fn request()->GenerationRequest{let(_,mut build,_,_)=crate::generation_test_fixture::fixture();build.policy_inputs.as_mut().unwrap().workspace_generators=vec![crate::GeneratorName::Deps];GenerationRequest{build,check:true}}fn metadata(request:&GenerationRequest)->Vec<u8>{serde_json::to_vec(&serde_json::json!({"schema":"native-generation-v1","clean":true,"committed":false,"rows":[{"generator":"deps","path":request.build.policy_inputs.as_ref().unwrap().workspace.as_ref().unwrap().root.join("code/engine/_generated/deps.dm"),"state":"fresh"}],"diagnostics":[],"changed":[],"cleanup":[]})).unwrap()}fn stage(request:&GenerationRequest,bytes:&[u8])->(Collector,GenerationTerminal){let file=crate::generation_staging::temporary_output(request.build.cache_root.as_ref().unwrap()).unwrap();let mut c=Collector::new(file);for chunk in bytes.chunks(3){c.push(c.fragments,c.total,chunk).unwrap();}let terminal=GenerationTerminal{status:Status::Completed,clean:true,fragments:c.fragments,total:c.total,hash:c.hash.digest128(),committed:false,may_have_changed:false,cleanup_warnings:0};(c,terminal)}
 #[test]fn generation_metadata_receiver_validates_all_fragments_before_emitting_and_refuses_bad_terminal(){let request=request();let bytes=metadata(&request);let(mut collector,terminal)=stage(&request,&bytes);let mut output=Vec::new();assert!(completed(&mut collector,&terminal,&request,&mut output).unwrap());assert_eq!(output.split(|b|*b==b'\n').filter(|row|!row.is_empty()).count(),2);let(mut collector,mut terminal)=stage(&request,&bytes);terminal.hash^=1;let mut output=Vec::new();assert!(completed(&mut collector,&terminal,&request,&mut output).is_err());assert!(output.is_empty());let(mut collector,terminal)=stage(&request,&bytes);assert!(collector.push(collector.fragments+1,collector.total,b"bad").is_err());let mut output=Vec::new();let mut wrong=terminal.clone();wrong.committed=true;assert!(completed(&mut collector,&wrong,&request,&mut output).is_err());assert!(output.is_empty());}
 #[test]fn generation_metadata_receiver_never_emits_a_valid_prefix_followed_by_invalid_document(){let request=request();let bytes=metadata(&request);let mut text=String::from_utf8(bytes).unwrap();text.push_str(" {} ");let(mut collector,terminal)=stage(&request,text.as_bytes());let mut output=Vec::new();assert!(completed(&mut collector,&terminal,&request,&mut output).is_err());assert!(output.is_empty());}
 #[test]fn generation_metadata_failure_restores_actual_os_error_source_and_never_emits_stdout(){let request=request();let bytes=serde_json::to_vec(&serde_json::json!({"schema":"native-generation-failure-v1","primary":{"kind":"Infrastructure","message":"actual native resource failure","os_code":1450,"io_kind":"Other"},"rollback":[],"cleanup":[],"committed":true})).unwrap();let(mut collector,mut terminal)=stage(&request,&bytes);terminal.status=Status::Failed;terminal.clean=false;terminal.committed=true;terminal.may_have_changed=true;let mut output=Vec::new();let error=completed(&mut collector,&terminal,&request,&mut output).err().unwrap();assert_eq!(error.source().unwrap().downcast_ref::<io::Error>().unwrap().raw_os_error(),Some(1450));assert!(error.to_string().contains("committed"));assert!(output.is_empty());}
 #[test]fn generation_metadata_receiver_rejects_hash_valid_check_reply_claiming_any_write_before_stdout(){
  let request=request();for case in 0..3{let mut value:serde_json::Value=serde_json::from_slice(&metadata(&request)).unwrap();if case==0{value["committed"]=true.into();}if case==1{value["rows"][0]["state"]="written".into();}if case==2{value["changed"]=serde_json::json!([request.build.policy_inputs.as_ref().unwrap().workspace.as_ref().unwrap().root.join("code/engine/_generated/deps.dm")]);}
   let bytes=serde_json::to_vec(&value).unwrap();let(mut collector,mut terminal)=stage(&request,&bytes);if case==0{terminal.committed=true;terminal.may_have_changed=true;}let mut output=Vec::new();let error=completed(&mut collector,&terminal,&request,&mut output).err().expect("valid fragment hash must not authorize a write claim for check mode");assert!(error.to_string().contains("check-only"));assert!(output.is_empty());
  }
 }

}
